O.extra.push({id:'order',title:'Ряд масти по порядку',fmt:'расставьте по рангу',desc:'Шесть карт масти вперемешку, имена закрыты. Расставьте их от Туза к Королю по рисунку.',mode:'sort',count:1,
 gen:function(){return null;}});O.extra.pop();
O.extra.push({id:'order',title:'Ряд масти по порядку',fmt:'расставьте по рангу',desc:'Пять карт масти вперемешку. Расставьте их от младшей к старшей.',mode:'order',count:10,
 gen:function(){var s=SH(ids).slice(0,5).sort();return {q:'Нажимайте на карты от младшей к старшей.',items:s.map(function(i){return D.name(i);}),e:s.map(function(i){return D.name(i);}).join(' → ')};}});
O.extra.push({id:'two',title:'Две похожие карты',fmt:'какая из двух',desc:'Две карты масти рядом и одно толкование. Решите, к какой из них оно относится.',mode:'mcq',count:16,
 gen:function(){var a=P(ids),b=P(ids.filter(function(x){return x!==a;}));var c=CF[a];return {q:'К какой из двух карт относится толкование?',story:c.open.replace(new RegExp(D.name(a).split(' ')[0]+'[а-яё]{0,3} '+D.name(a).split(' ')[1].slice(0,-2)+'[а-яё]{0,3}','g'),'«…»'),img:[a,b].sort(),o:[D.name(a),D.name(b)],a:0};}});
