(function(){
var D=DECK,P=function(a){return a[Math.floor(Math.random()*a.length)];},SH=TRU.shuf,CF=window.CF,O=window.LOPT;
var IDS=O.ids,ALL=IDS.map(function(i){return CF[i];});
function nm(id){return D.name(id);}
function cut(s,n){n=n||220;if(!s)return '';if(s.length<=n)return s;var c=s.slice(0,n);var p=c.lastIndexOf('. ');return (p>80?c.slice(0,p+1):c.replace(/\s\S*$/,'')+'…');}
var SUITW=['Мечей','Жезлов','Кубков','Пентаклей'];
function root(w){var r=w;if(r.length>4)r=r.slice(0,-1);else if(r.length===4&&/[аяеиоуыэюё]$/.test(r))r=r.slice(0,-1);if(/[ьй]$/.test(r))r=r.slice(0,-1);return r.replace(/[ёе]/g,'[ёе]')+'[а-яё]{0,3}';}
function rootRe(name){return name.split(' ').map(root).join('\\s+');}
function mask(t,id){if(!t)return t;var n=nm(id);n.split(' ').forEach(function(w){if(w.length<3||SUITW.indexOf(w)>=0)return;var re=new RegExp('(^|[^а-яёА-ЯЁ])('+root(w)+')(?![а-яё])','g');t=t.replace(re,'$1«…»');});
  t=t.replace(/«…»\s+«…»/g,'«…»');if(n==='Правосудие')t=t.replace(/Справедливост[а-яё]*/g,'«…»');return t;}
function maskAll(t){IDS.forEach(function(i){t=mask(t,i);});return t;}
function others(id,k){return SH(IDS.filter(function(x){return x!==id;})).slice(0,k);}
function mcq(q,right,wrong,extra){var o=[right].concat(wrong);var it={q:q,o:o,a:0};for(var k in extra)it[k]=extra[k];return it;}
var SPH=[['love','Отношения','отношения и семью'],['work','Работа','работу'],['money','Деньги','деньги'],['sit','Ситуация','развитие ситуации'],['mag','Магия','магическую диагностику'],['rev','Перевёрнутое','перевёрнутое положение']];
function sec(c,pref){for(var k in c.secs)if(k.indexOf(pref)===0&&c.secs[k])return c.secs[k];if(pref==='Работа')for(var k2 in c.secs)if(k2.indexOf('Работа и деньги')===0)return c.secs[k2];if(pref==='Деньги')for(var k3 in c.secs)if(k3.indexOf('Работа и деньги')===0)return null;return null;}
var T=[];
// 1 flash
T.push({id:'flash',title:'Карточки для запоминания',fmt:'флеш-карты',desc:'Смотрите на рисунок, вспоминаете принцип карты и как она ведёт себя в человеке, потом переворачиваете.',mode:'flash',count:IDS.length*2,
 gen:function(){var c=P(ALL);var p=c.person||{};return {img:c.id,front:'Что это за карта и в чём её главный принцип?',back:nm(c.id)+'\n\n'+(c.open||'')+'\n\n'+Object.keys(p).map(function(k){return k+': '+p[k];}).join('\n'),showName:false};}});
// 2 blitz
T.push({id:'blitz',title:'Блиц: узнай по рисунку',fmt:'на время, 6 секунд',desc:'Название и номер на рисунке закрыты. Узнайте карту по сюжету.',mode:'mcq',timer:6,count:24,
 gen:function(){var c=P(ALL);return mcq('Какая это карта?',nm(c.id),others(c.id,3).map(nm),{img:[c.id],noname:true,big:true,e:c.open});}});
// 3 principle
T.push({id:'princ',title:'Главный принцип',fmt:'выбор из четырёх',desc:'Под картой четыре формулировки принципа. Только одна написана для неё.',mode:'mcq',count:20,
 gen:function(){var c=P(ALL);return mcq('Какой принцип описывает эту карту?',maskAll(c.open),others(c.id,3).map(function(x){return maskAll(CF[x].open);}),{img:[c.id],noname:true,e:c.rem[0]||''});}});
// 4 desc
T.push({id:'desc',title:'Карта по описанию рисунка',fmt:'описание → карта',desc:'Читаете описание рисунка, где название закрыто, и выбираете карту.',mode:'mcq',count:20,
 gen:function(){var c=P(ALL);return mcq('Какую карту описывает этот текст?',nm(c.id),others(c.id,3).map(nm),{story:maskAll(c.vis&&c.vis.length>80?c.vis:(c.secs['Что изображено']||c.vis))});}});
// 5 detail
var DET=[];ALL.forEach(function(c){(c.det||[]).forEach(function(r){if(r[2]&&r[2].length>8)DET.push({id:c.id,d:r[0],w:r[1],r:r[2]});});});
if(DET.length>=8)T.push({id:'detail',title:'Деталь рисунка',fmt:'деталь → как читается',desc:'Деталь конкретной карты и четыре прочтения. Нужно выбрать то, что из этой детали следует.',mode:'mcq',count:24,
 gen:function(){var x=P(DET);var w=SH(DET.filter(function(y){return y.r!==x.r&&y.d!==x.d;})).slice(0,3).map(function(y){return y.r;});return mcq(nm(x.id)+'. Деталь: «'+x.d+'»'+(x.w&&x.w!==x.d?' ('+x.w+')':'')+'. Как она читается?',x.r,w,{img:[x.id]});}});
// 6 person match
var PK=['Мысли','Чувства','Намерения','Поступки'];
T.push({id:'person',title:'Карта как человек',fmt:'соедините пары',desc:'Четыре карты и четыре описания: что человек думает, чувствует, хочет или делает. Соедините.',mode:'match',count:10,
 gen:function(){var k=P(PK);var cs=SH(ALL.filter(function(c){return c.person&&c.person[k];})).slice(0,4);return {q:k+' человека. Соедините карту с описанием.',pairs:cs.map(function(c){return ['#'+c.id,maskAll(c.person[k])];})};}});
// 7 sphere
T.push({id:'sphere',title:'Карта в теме вопроса',fmt:'тема → прочтение',desc:'Одна карта, конкретная тема вопроса и четыре прочтения. Три из них написаны для других карт этой же темы.',mode:'mcq',count:24,
 gen:function(){for(var g=0;g<50;g++){var c=P(ALL),s=P(SPH.slice(0,5));var r=sec(c,s[1]);if(!r)continue;var w=others(c.id,6).map(function(x){return sec(CF[x],s[1]);}).filter(Boolean).slice(0,3);if(w.length<3)continue;
  return mcq('Вопрос про '+s[2]+'. Выпала эта карта. Какое прочтение ей подходит?',maskAll(cut(r,260)),w.map(function(x){return maskAll(cut(x,260));}),{img:[c.id],e:nm(c.id)});}}});
// 8 reversed
T.push({id:'rev',title:'Перевёрнутое положение',fmt:'карта вниз головой',desc:'Карта лежит перевёрнутой. Выберите описание перевёрнутого положения именно этой карты.',mode:'mcq',count:16,
 gen:function(){var c=P(ALL.filter(function(c){return sec(c,'Перевёрнутое');}));return mcq('Карта выпала перевёрнутой. Что это скорее значит?',maskAll(cut(sec(c,'Перевёрнутое'),300)),others(c.id,5).map(function(x){return sec(CF[x],'Перевёрнутое');}).filter(Boolean).slice(0,3).map(function(t){return maskAll(cut(t,300));}),{img:[c.id+'r'],e:nm(c.id)});}});
// 9 story (examples)
var EX=[];ALL.forEach(function(c){(c.ex||[]).forEach(function(t){EX.push({id:c.id,t:t});});(c.prac||[]).forEach(function(p){});});
T.push({id:'story',title:'Какая карта в этой истории',fmt:'история → карта',desc:'Короткая история из практики, название карты закрыто. По сюжету определите, какая карта выпала.',mode:'mcq',count:Math.min(EX.length,16),
 gen:function(){var x=P(EX);return mcq('Какая карта стоит за «…» в этой истории?',nm(x.id),others(x.id,3).map(nm),{story:mask(cut(x.t,700),x.id)});}});
// 10 combo
var CB=[];ALL.forEach(function(c){(c.combo||[]).forEach(function(p){if(p[1].length>30)CB.push({id:c.id,h:p[0],t:p[1]});});});
if(CB.length>=6)T.push({id:'combo',title:'Сочетания и сравнения',fmt:'пара → смысл',desc:'Названа пара карт. Выберите, что о ней сказано в уроке.',mode:'mcq',count:Math.min(CB.length,20),
 gen:function(){var x=P(CB);return mcq((new RegExp(rootRe(nm(x.id).split(' ')[0])).test(x.h)?'':nm(x.id)+': ')+x.h.replace(/\.$/,'')+'. Что сказано в уроке про это сочетание?',x.t,SH(CB.filter(function(y){return y.h!==x.h;})).slice(0,3).map(function(y){return y.t;}),{img:[x.id]});}});
// 11 positions (minors)
var PS=[];ALL.forEach(function(c){(c.pos||[]).forEach(function(p){PS.push({id:c.id,h:p[0],t:p[1]});});});
if(PS.length>=8)T.push({id:'pos',title:'Карта в позиции расклада',fmt:'позиция → прочтение',desc:'Карта стоит в определённой позиции расклада. Какое прочтение подходит этой карте в этой позиции?',mode:'mcq',count:20,
 gen:function(){var x=P(PS);var w=SH(PS.filter(function(y){return y.id!==x.id&&y.h===x.h;}));if(w.length<3)w=w.concat(SH(PS.filter(function(y){return y.id!==x.id&&y.h!==x.h;})));return mcq('Позиция: «'+x.h+'». Как читается эта карта?',maskAll(x.t),w.slice(0,3).map(function(y){return maskAll(y.t);}),{img:[x.id],e:nm(x.id)});}});
// 12 errors tf
var TF=[];ALL.forEach(function(c){(c.err||[]).forEach(function(t){var s=t.split(/(?<=[.!?])\s+/);TF.push({s:'Типичное толкование: «'+s[0]+'» ('+nm(c.id)+'). Это верный подход?',a:false,e:s.slice(1).join(' '),img:[c.id]});});(c.rem||[]).forEach(function(t){TF.push({s:t,a:true,img:[c.id]});var o=P(IDS.filter(function(x){return x!==c.id;}));TF.push({s:t.replace(new RegExp(rootRe(nm(c.id))),nm(o)),a:false,e:'Это сказано про карту «'+nm(c.id)+'».',img:[o]});});});
T.push({id:'tf',title:'Верно или ошибка',fmt:'да / нет',desc:'Утверждения и типичные толкования начинающих. Решите, можно ли так читать карту.',mode:'tf',items:TF,count:Math.min(TF.length,24)});
// 13 cases
var CS=[];ALL.forEach(function(c){(c.prac||[]).forEach(function(p){CS.push({story:p[0],img:[c.id],q:'Ответьте письменно, затем откройте разбор.',model:p[1]});});});
T.push({id:'case',title:'Практика с разбором',fmt:'письменный ответ',desc:'Задания из урока. Пишете свой ответ, открываете образец и честно оцениваете, совпало ли по сути.',mode:'case',items:CS,count:Math.min(CS.length,12)});
(O.extra||[]).forEach(function(x){T.push(x);});
window.LESSON={key:O.key,kick:O.kick,title:O.title,sub:O.sub.replace('13 ',T.length+' '),trainers:T};
})();
